import sys
from pathlib import Path
import argparse

root = Path(__file__).parent.parent

# Lets users know not to edit the file directly because it is automatically generated
HEADER = (
    "# Generated by build_ollama_modelfile.py - do not edit directly.\n"
    "# Source of truth: the markdown files in this repository.\n"
    "# Re-run build_ollama_modelfile.py after updating any source files.\n"
    "# See CONTRIBUTING.md and README.md for details."
)

def collect_sources() -> list[Path]:
    """
    Developer-defined set of files and directories to search for content that needs
    to be included in the modelfile.
    """
    sources = [root / "SKILL.md"]
    sources.extend(sorted((root / "concepts").glob("*.md")))
    sources.extend(sorted((root / "patterns").glob("*.md")))
    examples = root / "examples"
    if examples.exists():
        sources.extend(sorted(examples.glob("*.py")))
    return sources


def build_system_prompt() -> str:
    """
    Concatenates all the files from the skill into a single prompt string for the
    Ollama LLM.
    """
    parts = []
    for path in collect_sources():
        if not path.exists():
            print(f"WARNING: {path.relative_to(root)} not found, skipping.", file=sys.stderr)
            continue
        rel = path.relative_to(root)
        parts.append(f"# {rel}\n\n{path.read_text()}")
    return "\n\n---\n\n".join(parts)


def main() -> None:
    parser = argparse.ArgumentParser(description="Build Ollama Modelfile from skill sources")
    parser.add_argument("--model", default="qwen2.5-coder:14b", help="Base Ollama model (default: qwen2.5-coder:14b)")
    parser.add_argument("--output", default="Modelfile", help="Output file (default: Modelfile)")
    args = parser.parse_args()

    system_prompt = build_system_prompt()
    if '"""' in system_prompt:
        print(
            "WARNING: Source content contains triple quoted strings. Modelfile SYSTEM block may be malformed.",
            file=sys.stderr,
        )

    lines = [
        HEADER,
        "",
        f"FROM {args.model}",
        "",
        "PARAMETER temperature 0.2",
        "",
        'SYSTEM """',
        system_prompt,
        '"""',
        "",
    ]

    output = root / args.output
    output.write_text("\n".join(lines))
    print(f"Wrote {output}")


if __name__ == "__main__":
    main()

